import{_ as a,o as i,c as s,a5 as t}from"./chunks/framework.BwlBv862.js";const k=JSON.parse('{"title":"国際化とアクセシビリティ","description":"","frontmatter":{"title":"国際化とアクセシビリティ","docId":"developer.i18n-accessibility","translationKey":"developer.i18n-accessibility","locale":"ja","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"2c74fcefd1d28353b1135c547b2e3e6ae852af8b683350011732d10c364f9323","translationRevision":"e646dfb8972a1a6eb5bba44b50ba654f197906784f0a78b1003c9227c608851e","order":120},"headers":[],"relativePath":"ja/developer/i18n-accessibility.md","filePath":"ja/developer/i18n-accessibility.md","lastUpdated":1794611623000}'),o={name:"ja/developer/i18n-accessibility.md"};function n(l,e,c,d,r,p){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="internationalization-and-accessibility" tabindex="-1">国際化とアクセシビリティ <a class="header-anchor" href="#internationalization-and-accessibility" aria-label="Permalink to &quot;国際化とアクセシビリティ {#internationalization-and-accessibility}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目的と前提条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>対応言語で理解でき、キーボード、タッチ、支援技術で使える画面を追加します。<a href="./frontend.html">フロントエンドの層</a> を読み、既存の共有 UI を使います。実行時のアプリ言語と公開文書の言語版は別の仕組みです。</p><h2 id="add-localized-content" tabindex="-1">翻訳内容を追加する <a class="header-anchor" href="#add-localized-content" aria-label="Permalink to &quot;翻訳内容を追加する {#add-localized-content}&quot;">​</a></h2><p>アプリのカタログは <code>src/web/shared/i18n/</code> にあります。英語が型付きの代替言語で、他の対応カタログはすべて遅延読み込みします。<code>activateLocale</code> が選んだメッセージを読み、<code>document.documentElement.lang</code> を更新します。別の local-storage キーを作らず、既存言語ストアで設定を保存します。</p><ol><li>意味に基づくメッセージキーを英語カタログと対応する各カタログ・モジュールに追加します。</li><li>API ID、イベントパス、保存リソース識別子は保ち、見えるラベルを翻訳します。</li><li>可変テキストは補間を使い、表示値は共有の国際化ヘルパーを使います。</li><li>プラグイン記述子は既存の <code>{default,i18key}</code> 契約とホストが統合したカタログを使います。翻訳文字列やプラグイン提供文字列を HTML として描画しません。</li></ol><h2 id="preserve-control-semantics" tabindex="-1">操作の意味を保つ <a class="header-anchor" href="#preserve-control-semantics" aria-label="Permalink to &quot;操作の意味を保つ {#preserve-control-semantics}&quot;">​</a></h2><p><code>BaseTextField</code>、<code>BaseFormRow</code>、<code>BaseDialog</code>、タブ、状態部品を優先します。プレースホルダーはアクセシブルなラベルの代わりになりません。アイコンボタンには翻訳された名前が必要です。検証は対象フィールドと無効状態を示し、色だけで失敗を伝えません。ダイアログからのフォーカス復帰、Escape、キーボード選択、見える輪郭を維持します。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i18n</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> catalogs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BaseDialog</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend-lint</span></span></code></pre></div><p>手動確認では全手順を Tab でたどり、ダイアログを開閉し、開いたまま言語を変え、狭幅でも繰り返します。ホバーで現れる状態操作はキーボードフォーカスでも表示し、タッチでも使えるようにします。</p><h2 id="expected-result-and-status" tabindex="-1">期待される結果と提供状況 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;期待される結果と提供状況 {#expected-result-and-status}&quot;">​</a></h2><p>カタログの型と整合性検査は不足キーを検出し、共有操作部品はキーボードと ARIA の実装を提供します。組み合わせた全画面の包括的なアクセシビリティ認証ではありません。翻訳文字列が存在してもランキングとコンテストは非表示のままです。</p><h2 id="recovery" tabindex="-1">問題が起きたとき <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;問題が起きたとき {#recovery}&quot;">​</a></h2><p>未翻訳が出たら、部品に英語の代替を追加する前に遅延読み込みとキーの綴りを確認します。フォーカスが消えたら転送属性の受信部品とダイアログの復帰先を確認します。現行動作は <a href="https://github.com/nglmercer/TikTools-app/blob/remake/src/web/shared/i18n/i18n.ts" target="_blank" rel="noreferrer">i18n 実装</a> と部品テストが定義し、<a href="./components/">コンポーネント</a> が共有入口を説明します。</p><h2 id="operational-details" tabindex="-1">運用の詳細 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;運用の詳細 {#operational-details}&quot;">​</a></h2><p>言語優先順は保存 <code>tiktok-live-locale</code> → <code>navigator.languages</code> → 英語です。<code>normalizeLocale</code> は地域タグと <code>jp</code> → <code>ja</code> を扱います。コード/書式地域は <code>en/en-US</code>・<code>es/es-ES</code>・<code>pt/pt-BR</code>・<code>fr/fr-FR</code>・<code>zh/zh-CN</code>・<code>ja/ja-JP</code> で、<code>intl.ts</code> の formatCount/formatDate を使います。<code>activateLocale</code> はメッセージ/lang を変え、<code>useLocaleStore().setLocale</code> は保存と最善努力の設定 staging も行います。設定 UI は store を使います。英語 fallback、zh/ja は host メッセージも読みます。追加時は supported-locales・loader・catalog/host・地域対応・設定テスト・キー/placeholder/複数形/コンパイル試験・docs/site routing を更新し、API ID・引数名は保持します。</p><p>余白・字形・control・focus・層の token を使います。粗い pointer または幅 700px 未満で control は 44px、navigation は 900px 未満、form 行は 600px 未満で別々に変化します。reduced motion は時間を 0 にします。広い画面でも粗 pointer を試します。全体は dark で light override は JSON 限定です。</p><p>キーボード：tab は矢印/Home/End で自動選択、select は矢印/Home/End/Enter と Escape 取消、menu は trigger へ focus を返します。dialog は native showModal ですが <code>closable=false</code> は Escape を拒否し、閉じると内容を unmount します。草稿は所有者に置き初期・復帰 focus を確認します。icon button は <code>label</code> が必須で <code>hint</code>/tooltip は説明のみ。tooltip は hover/focus 500ms 後に現れ Escape で閉じ、dialog の top layer に入ります。実際の支援操作は手動確認し、unit test を画面全体の認証にしません。</p>`,18)])])}const u=a(o,[["render",n]]);export{k as __pageData,u as default};
